+package model
+
+import (
+	"testing"
+
+	"github.com/sashabaranov/go-openai"
+	"github.com/stretchr/testify/require"
+	"github.com/tiktoken-go/tokenizer/codec"
+)
+
+func TestTokenCounters(t *testing.T) {
+	tokenizer := codec.NewCl100kBase()
+	encodeLen := func(s string) int {
+		tokens, _, err := tokenizer.Encode(s)
+		require.NoError(t, err)
+		return len(tokens)
+	}
+
+	prompt, err := NewPromptTokenCounter([]openai.ChatCompletionMessage{
+		{Role: openai.ChatMessageRoleSystem, Content: "Hello"},
+		{Role: openai.ChatMessageRoleUser, Content: "Hi there"},
+	})
+	require.NoError(t, err)
+	completion, err := NewSynchronousTokenCounter("A response")
+	require.NoError(t, err)
+	count := NewTokenCount()
+	count.AddPromptCounter(nil)
+	count.AddCompletionCounter(nil)
+	count.AddPromptCounter(prompt)
+	count.AddCompletionCounter(completion)
+	p, c := count.CountAll()
+	require.Equal(t, 2*(perMessage+perRole)+encodeLen("Hello")+encodeLen("Hi there"), p)
+	require.Equal(t, perRequest+encodeLen("A response"), c)
+}
+
+func TestAsynchronousTokenCounter(t *testing.T) {
+	counter, err := NewAsynchronousTokenCounter("start")
+	require.NoError(t, err)
+	require.NoError(t, counter.Add())
+	want := perRequest + 2
+	require.Equal(t, want, counter.TokenCount())
+	require.Equal(t, want, counter.TokenCount())
+	require.Error(t, counter.Add())
+}
